/// One `drawText` call (render.ts:1636-1707) with every model-derived value precomputed (decision T1); the
/// painter replays it in the TS order, including the fit.
#[derive(Debug, Clone, PartialEq)]
pub struct TextRun {
    pub text: Span,
    pub font: FontRef,
    pub x: f64,
    /// the baseline, including `rise x scale`
    pub y: f64,
    /// `r.w x scale` when the text is the whole run text; absent for unit pieces
    pub laid_w: Option<f64>,
    /// `!ls && text === r.text && !st` (the painter adds its own `prevLs !== undefined`)
    pub fit_allowed: bool,
    /// `r.spc x scale` (0 = none)
    pub letter_spacing_px: f64,
    /// `fontKerning = kern ? 'normal' : 'none'` when supported
    pub kern: bool,
    pub fill: Paint,
    /// `fillA < 1`: `globalAlpha x fillA`
    pub alpha_mul: Option<f64>,
    pub shadow: Option<TextShadow>,
    /// false when fillA <= 0 (outline only)
    pub fill_text: bool,
    pub outline: Option<TextOutline>,
    pub underline: Option<Decoration>,
    pub strike: Option<Decoration>,
}

impl TextRun {
    /// The least number of bits an element takes on the wire.
    pub const MIN_BITS: u64 = 312;

    pub fn encode(&self, w: &mut Writer<'_>) {
        w.bitmap(&[self.laid_w.is_some(), self.fit_allowed, self.kern, self.alpha_mul.is_some(), self.shadow.is_some(), self.fill_text, self.outline.is_some(), self.underline.is_some(), self.strike.is_some()]);
        self.text.encode(w);
        self.font.encode(w);
        w.f64(self.x);
        w.f64(self.y);
        if let Some(v) = self.laid_w {
            w.f64(v);
        }
        w.f64(self.letter_spacing_px);
        self.fill.encode(w);
        if let Some(v) = self.alpha_mul {
            w.f64(v);
        }
        if let Some(v) = &self.shadow {
            v.encode(w);
        }
        if let Some(v) = &self.outline {
            v.encode(w);
        }
        if let Some(v) = &self.underline {
            v.encode(w);
        }
        if let Some(v) = &self.strike {
            v.encode(w);
        }
    }

    pub fn decode(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        let bm = r.bitmap(9)?;
        let f_text = Span::decode(r)?;
        let f_font = FontRef::decode(r)?;
        let f_x = r.f64()?;
        let f_y = r.f64()?;
        let f_laid_w = if bit(bm, 0) { Some(r.f64()?) } else { None };
        let f_fit_allowed = bit(bm, 1);
        let f_letter_spacing_px = r.f64()?;
        let f_kern = bit(bm, 2);
        let f_fill = Paint::decode(r)?;
        let f_alpha_mul = if bit(bm, 3) { Some(r.f64()?) } else { None };
        let f_shadow = if bit(bm, 4) { Some(TextShadow::decode(r)?) } else { None };
        let f_fill_text = bit(bm, 5);
        let f_outline = if bit(bm, 6) { Some(TextOutline::decode(r)?) } else { None };
        let f_underline = if bit(bm, 7) { Some(Decoration::decode(r)?) } else { None };
        let f_strike = if bit(bm, 8) { Some(Decoration::decode(r)?) } else { None };
        Ok(Self { text: f_text, font: f_font, x: f_x, y: f_y, laid_w: f_laid_w, fit_allowed: f_fit_allowed, letter_spacing_px: f_letter_spacing_px, kern: f_kern, fill: f_fill, alpha_mul: f_alpha_mul, shadow: f_shadow, fill_text: f_fill_text, outline: f_outline, underline: f_underline, strike: f_strike })
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum Effect {
    Bevel(BevelEffect),
    Warp(WarpEffect),
    MetafileRop(MetafileRopEffect),
}

impl Effect {
    /// The least number of bits a value takes on the wire.
    pub const MIN_BITS: u64 = 280;

    pub fn encode(&self, w: &mut Writer<'_>) {
        match self {
            Self::Bevel(v) => {
                w.u32(0);
                v.encode(w);
            }
            Self::Warp(v) => {
                w.u32(1);
                v.encode(w);
            }
            Self::MetafileRop(v) => {
                w.u32(2);
                v.encode(w);
            }
        }
    }

    pub fn decode(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        let tag = r.u32()?;
        let value = match tag {
            0 => Self::Bevel(BevelEffect::decode(r)?),
            1 => Self::Warp(WarpEffect::decode(r)?),
            2 => Self::MetafileRop(MetafileRopEffect::decode(r)?),
            _ => return Err(DecodeError::BadTag { ty: "Effect", tag }),
        };
        Ok(value)
    }
}

/// `applyBevel`: the silhouette is the path span; the shell reads the device rect (`getImageData`), so it is code.
/// The light table is looked up by `rig`/`mat` in the shell (uo-drawingml `light3d`).
#[derive(Debug, Clone, PartialEq)]
pub struct BevelEffect {
    pub path: Span,
    pub rule: FillRule,
    pub bx: Rect4,
    /// the bevel width and height in model units (`b.w`, `b.h`); the painter multiplies by `scale` and the device scale
    pub w: f64,
    pub h: f64,
    pub scale: f64,
    pub prst: Option<u32>,
    pub rig: Option<u32>,
    pub mat: Option<u32>,
}

impl BevelEffect {
    /// The least number of bits an element takes on the wire.
    pub const MIN_BITS: u64 = 480;

    pub fn encode(&self, w: &mut Writer<'_>) {
        w.bitmap(&[self.prst.is_some(), self.rig.is_some(), self.mat.is_some()]);
        self.path.encode(w);
        self.rule.encode(w);
        self.bx.encode(w);
        w.f64(self.w);
        w.f64(self.h);
        w.f64(self.scale);
        if let Some(v) = self.prst {
            w.u32(v);
        }
        if let Some(v) = self.rig {
            w.u32(v);
        }
        if let Some(v) = self.mat {
            w.u32(v);
        }
    }

    pub fn decode(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        let bm = r.bitmap(3)?;
        let f_path = Span::decode(r)?;
        let f_rule = FillRule::decode(r)?;
        let f_bx = Rect4::decode(r)?;
        let f_w = r.f64()?;
        let f_h = r.f64()?;
        let f_scale = r.f64()?;
        let f_prst = if bit(bm, 0) { Some(r.ref_in(0, "sym")?) } else { None };
        let f_rig = if bit(bm, 1) { Some(r.ref_in(0, "sym")?) } else { None };
        let f_mat = if bit(bm, 2) { Some(r.ref_in(0, "sym")?) } else { None };
        Ok(Self { path: f_path, rule: f_rule, bx: f_bx, w: f_w, h: f_h, scale: f_scale, prst: f_prst, rig: f_rig, mat: f_mat })
    }
}

/// `paintWarp` from the laid-out lines on (render.ts:1868-1984 and text-warp.ts).
#[derive(Debug, Clone, PartialEq)]
pub struct WarpEffect {
    pub prst: u32,
    pub adj: Option<Vec<f64>>,
    pub from_word_art: bool,
    pub bx: Rect4,
    pub px_per_pt: f64,
    pub lines: Vec<WarpLine>,
    /// the canvas shadow parameters of the layer composite (already x scale and x the blur constant)
    pub shadow: Option<TextShadow>,
    /// a tiled picture over the warped silhouette (`source-in`): image, scale, offset in px
    pub tile: Option<WarpTile>,
}

impl WarpEffect {
    /// The least number of bits an element takes on the wire.
    pub const MIN_BITS: u64 = 344;

    pub fn encode(&self, w: &mut Writer<'_>) {
        w.bitmap(&[self.adj.is_some(), self.from_word_art, self.shadow.is_some(), self.tile.is_some()]);
        w.u32(self.prst);
        if let Some(v) = &self.adj {
            w.len(v.len());
            for e0 in v.iter().copied() {
                w.f64(e0);
            }
        }
        self.bx.encode(w);
        w.f64(self.px_per_pt);
        w.len(self.lines.len());
        for e0 in self.lines.iter() {
            e0.encode(w);
        }
        if let Some(v) = &self.shadow {
            v.encode(w);
        }
        if let Some(v) = &self.tile {
            v.encode(w);
        }
    }

    pub fn decode(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        let bm = r.bitmap(4)?;
        let f_prst = r.ref_in(0, "sym")?;
        let f_adj = if bit(bm, 0) { Some({ let n = r.list_of::<f64>(64)?; let mut v = Vec::with_capacity(n); for _ in 0..n { v.push(r.f64()?); } v }) } else { None };
        let f_from_word_art = bit(bm, 1);
        let f_bx = Rect4::decode(r)?;
        let f_px_per_pt = r.f64()?;
        let f_lines = { let n = r.list_of::<WarpLine>(152)?; let mut v = Vec::with_capacity(n); for _ in 0..n { v.push(WarpLine::decode(r)?); } v };
        let f_shadow = if bit(bm, 2) { Some(TextShadow::decode(r)?) } else { None };
        let f_tile = if bit(bm, 3) { Some(WarpTile::decode(r)?) } else { None };
        Ok(Self { prst: f_prst, adj: f_adj, from_word_art: f_from_word_art, bx: f_bx, px_per_pt: f_px_per_pt, lines: f_lines, shadow: f_shadow, tile: f_tile })
    }
}

