#[derive(Debug, Clone, PartialEq)]
pub struct WarpLine {
    pub runs: Vec<WarpRun>,
    pub baseline: f64,
    pub size_pt: f64,
    pub height: Option<f64>,
    pub ln_pct: Option<f64>,
    pub align: u32,
    pub trailing: Option<f64>,
}

impl WarpLine {
    /// The least number of bits an element takes on the wire.
    pub const MIN_BITS: u64 = 152;

    pub fn encode(&self, w: &mut Writer<'_>) {
        w.bitmap(&[self.height.is_some(), self.ln_pct.is_some(), self.trailing.is_some()]);
        w.len(self.runs.len());
        for e0 in self.runs.iter() {
            e0.encode(w);
        }
        w.f64(self.baseline);
        w.f64(self.size_pt);
        if let Some(v) = self.height {
            w.f64(v);
        }
        if let Some(v) = self.ln_pct {
            w.f64(v);
        }
        w.u32(self.align);
        if let Some(v) = self.trailing {
            w.f64(v);
        }
    }

    pub fn decode(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        let bm = r.bitmap(3)?;
        let f_runs = { let n = r.list_of::<WarpRun>(160)?; let mut v = Vec::with_capacity(n); for _ in 0..n { v.push(WarpRun::decode(r)?); } v };
        let f_baseline = r.f64()?;
        let f_size_pt = r.f64()?;
        let f_height = if bit(bm, 0) { Some(r.f64()?) } else { None };
        let f_ln_pct = if bit(bm, 1) { Some(r.f64()?) } else { None };
        let f_align = r.ref_in(0, "sym")?;
        let f_trailing = if bit(bm, 2) { Some(r.f64()?) } else { None };
        Ok(Self { runs: f_runs, baseline: f_baseline, size_pt: f_size_pt, height: f_height, ln_pct: f_ln_pct, align: f_align, trailing: f_trailing })
    }
}

